+const ID = /^[a-z][a-z0-9-]{0,31}$/;
+const JOB_FIELDS = new Set(['id', 'dependsOn', 'payload']);
+const STORED_FIELDS = new Set(['id', 'dependsOn', 'payload', 'status', 'attempt', 'result', 'error']);
+const STATUSES = new Set(['pending', 'running', 'completed', 'failed', 'blocked']);
+const clone = value => JSON.parse(JSON.stringify(value));
+const errorText = value => value && typeof value.message === 'string' ? value.message : String(value);
+
+function validateGraph(jobs) {
+  const ids = new Set();
+  for (const job of jobs) {
+    if (!job || typeof job !== 'object' || Array.isArray(job)) throw new Error('job must be an object');
+    if (typeof job.id !== 'string' || !ID.test(job.id)) throw new Error('invalid job id');
+    if (ids.has(job.id)) throw new Error(`duplicate job id: ${job.id}`);
+    ids.add(job.id);
+    if (!Array.isArray(job.dependsOn)) throw new Error(`invalid dependencies for ${job.id}`);
